# SIAMS-ALPHA-M1: generated by setup-alpha-apps.sh, safe to edit (re-runs skip it)
from datetime import date

import pytest

from apps.core.exceptions import InvalidTransition
from apps.placements.models import Placement

S = Placement.Status

ALLOWED = [
    (S.DRAFT, S.SUBMITTED),
    (S.SUBMITTED, S.APPROVED),
    (S.SUBMITTED, S.RETURNED),
    (S.SUBMITTED, S.REJECTED),
    (S.RETURNED, S.SUBMITTED),
    (S.APPROVED, S.COMPLETED),
    (S.APPROVED, S.TERMINATED),
]
FORBIDDEN = [
    (S.DRAFT, S.APPROVED),
    (S.DRAFT, S.COMPLETED),
    (S.SUBMITTED, S.COMPLETED),
    (S.RETURNED, S.APPROVED),
    (S.APPROVED, S.SUBMITTED),
    (S.REJECTED, S.SUBMITTED),
    (S.COMPLETED, S.TERMINATED),
    (S.TERMINATED, S.APPROVED),
]


@pytest.mark.parametrize(("current", "target"), ALLOWED)
def test_allowed_transitions(current, target):
    Placement(status=current).ensure_transition(target)


@pytest.mark.parametrize(("current", "target"), FORBIDDEN)
def test_forbidden_transitions(current, target):
    with pytest.raises(InvalidTransition):
        Placement(status=current).ensure_transition(target)


def test_can_log_only_when_approved_and_inside_dates():
    placement = Placement(status=S.APPROVED, start_date=date(2026, 1, 1), end_date=date(2026, 2, 1))
    assert placement.can_log_on(date(2026, 1, 15))
    assert not placement.can_log_on(date(2026, 2, 2))
    placement.status = S.SUBMITTED
    assert not placement.can_log_on(date(2026, 1, 15))
